import os
from pathlib import Path

import pytest

NOTES_DIR = "notes"


def read_note(name: str) -> str:
    """Return the text of the file `name` inside the directory `notes`.

    `notes` is resolved relative to the current working directory. `name`
    comes from an untrusted request and may be anything: absolute paths,
    `..` segments, symlinks, embedded NUL characters, an empty string, etc.

    Only files that really live inside `notes` (after resolving symlinks and
    `..`) may be read. If the file is missing, is not a regular file, is
    unreadable, or `name` would lead outside `notes` in any way, return "".
    Never raise.
    """
    try:
        if not name or "\x00" in name:
            return ""
        base = Path(NOTES_DIR).resolve()
        target = (base / name).resolve()
        if target == base or not target.is_relative_to(base):
            return ""
        if not target.is_file():
            return ""
        return target.read_text(encoding="utf-8")
    except (OSError, ValueError, RuntimeError):
        return ""


@pytest.fixture
def sandbox(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    notes = tmp_path / NOTES_DIR
    notes.mkdir()
    (notes / "a.txt").write_text("hello", encoding="utf-8")
    (notes / "uni.txt").write_text("héllo ✓", encoding="utf-8")
    (notes / "subdir").mkdir()
    (tmp_path / "secret.txt").write_text("SECRET", encoding="utf-8")
    (tmp_path / "notes_evil").mkdir()
    (tmp_path / "notes_evil" / "x.txt").write_text("EVIL", encoding="utf-8")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_reads_existing_file(sandbox: Path) -> None:
    assert read_note("a.txt") == "hello"


def test_reads_utf8(sandbox: Path) -> None:
    assert read_note("uni.txt") == "héllo ✓"


def test_missing_file_gives_empty(sandbox: Path) -> None:
    assert read_note("nope.txt") == ""


def test_empty_name_gives_empty(sandbox: Path) -> None:
    assert read_note("") == ""


def test_directory_gives_empty(sandbox: Path) -> None:
    assert read_note("subdir") == ""
    assert read_note(".") == ""


def test_parent_traversal_blocked(sandbox: Path) -> None:
    assert read_note("../secret.txt") == ""
    assert read_note("../../secret.txt") == ""
    assert read_note("subdir/../../secret.txt") == ""
    assert read_note("./../secret.txt") == ""


def test_sibling_directory_with_shared_prefix_blocked(sandbox: Path) -> None:
    assert read_note("../notes_evil/x.txt") == ""


def test_absolute_path_outside_blocked(sandbox: Path) -> None:
    assert read_note(str(sandbox / "secret.txt")) == ""
    assert read_note(str(sandbox / "notes_evil" / "x.txt")) == ""


def test_absolute_path_with_traversal_blocked(sandbox: Path) -> None:
    sneaky = str(sandbox / NOTES_DIR / ".." / "secret.txt")
    assert read_note(sneaky) == ""


def test_nul_byte_gives_empty(sandbox: Path) -> None:
    assert read_note("a.txt\x00") == ""
    assert read_note("a.txt\x00../secret.txt") == ""
    assert read_note("\x00") == ""


def test_encoded_traversal_is_just_a_missing_name(sandbox: Path) -> None:
    assert read_note("%2e%2e/secret.txt") == ""
    assert read_note("..%2fsecret.txt") == ""


def test_symlink_file_escaping_notes_blocked(sandbox: Path) -> None:
    link = sandbox / NOTES_DIR / "link.txt"
    try:
        os.symlink(sandbox / "secret.txt", link)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert read_note("link.txt") == ""


def test_symlinked_directory_escaping_notes_blocked(sandbox: Path) -> None:
    link = sandbox / NOTES_DIR / "outdir"
    try:
        os.symlink(sandbox / "notes_evil", link, target_is_directory=True)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert read_note("outdir/x.txt") == ""


def test_symlink_staying_inside_notes_is_ok(sandbox: Path) -> None:
    link = sandbox / NOTES_DIR / "alias.txt"
    try:
        os.symlink(sandbox / NOTES_DIR / "a.txt", link)
    except (OSError, NotImplementedError):
        pytest.skip("symlinks not supported")
    assert read_note("alias.txt") == "hello"


def test_unreadable_file_gives_empty(sandbox: Path) -> None:
    if os.name == "nt" or (hasattr(os, "geteuid") and os.geteuid() == 0):
        pytest.skip("permission bits not enforced")
    p = sandbox / NOTES_DIR / "locked.txt"
    p.write_text("x", encoding="utf-8")
    p.chmod(0)
    try:
        assert read_note("locked.txt") == ""
    finally:
        p.chmod(0o600)


def test_invalid_utf8_does_not_raise(sandbox: Path) -> None:
    (sandbox / NOTES_DIR / "bin.dat").write_bytes(b"\xff\xfe\x00\x80")
    assert isinstance(read_note("bin.dat"), str)


def test_missing_notes_directory_gives_empty(
    tmp_path: Path, monkeypatch: pytest.MonkeyPatch
) -> None:
    monkeypatch.chdir(tmp_path)
    assert read_note("a.txt") == ""
